import subprocess, os, tempfile, struct

def run(path, timeout=1):
    proc = subprocess.Popen(["./executable","-r",path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    try:
        out, err = proc.communicate(timeout=timeout)
        return err.strip()
    except subprocess.TimeoutExpired:
        proc.kill()
        out, err = proc.communicate()
        return "TIMEOUT:"+err[:500]

def make(data):
    fd, path = tempfile.mkstemp(dir="/tmp")
    os.write(fd, data)
    os.close(fd)
    return path

def test_len(n):
    data = struct.pack(">I", n) + b"A"*n
    p = make(data)
    err = run(p)
    os.unlink(p)
    if "String too long" in err:
        return "too long"
    elif "Bad buf_getptr" in err:
        return "bad buf"
    elif "Failed loading" in err:
        return "failed"
    else:
        return err[:500]

# binary search threshold
lo=0
hi=20000
for n in range(0,20000,100):
    r=test_len(n)
    if r!="failed":
        print(f"first non-failed at {n} -> {r}")
        lo=n
        break

# refine
for n in range(4000, 10000):
    r=test_len(n)
    if r!="failed":
        if r=="too long" or r=="bad buf":
            print(f"{n} -> {r}")

# find boundary between bad buf and too long
# We saw 4000 -> bad buf, 10000 -> too long. So middle.

for n in [4000,5000,6000,7000,8000,9000,10000,9000,8500,8000,8100,8200,8300,8400]:
    r=test_len(n)
    print(f"{n} -> {r}")

