import subprocess, os, tempfile, struct

def run(path):
    proc = subprocess.Popen(["./executable","-r",path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
    try:
        out, err = proc.communicate(timeout=1)
        return err.strip()
    except subprocess.TimeoutExpired:
        proc.kill()
        out, err = proc.communicate()
        return "TIMEOUT "+err[:500]

def make(data):
    fd, path = tempfile.mkstemp(dir="/tmp")
    os.write(fd, data)
    os.close(fd)
    return path

def classify(err):
    if "Not backgrounding" in err or "Failed listening" in err:
        return "SUCCESS"
    if "String too long" in err:
        return "STR_TOO_LONG"
    if "Bad buf_getptr" in err:
        return "BAD_BUF"
    if "Failed loading" in err:
        return "FAIL_LOAD"
    if "RSA key too short" in err:
        return "RSA_SHORT"
    return err[:500]

# test all zeros files of various sizes
for size in [0,1,2,3,4,5,10,20,100,1000,1696,1697,1700,1701,2000,4000,8000,9000,9001,10000]:
    data = b"\x00"*size
    p = make(data)
    err = run(p)
    print(f"zeros size {size} -> {classify(err)} : {err[:300]}")
    os.unlink(p)

# test single string with 'A' but with len = N, total size 4+N
print("--- single string A ---")
for N in [0,1,1000,1660,1696,1697,1700,2000,4000,8000,9000,9001]:
    data = struct.pack(">I", N)+b"A"*N
    p = make(data)
    err = run(p)
    print(f"N {N} size {len(data)} -> {classify(err)}")
    os.unlink(p)

PY
python3 /tmp/test_size.py 2>&1 | head -n 200
"}

