int parse_int_full(const char *s, long *out) {
    if (s == NULL || *s == '\0') return 0;
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0) return 0;
    if (*end != '\0') return 0;
    *out = v;
    return 1;
}

