    fprintf(stderr, "-P PidFile\tCreate pid file PidFile\n");
    fprintf(stderr, "\t\t(default /var/run/dropbear.pid)\n");
    fprintf(stderr, "-l <interface>\n");
    fprintf(stderr, "\t\tinterface to bind on\n");
    fprintf(stderr, "-i\t\tStart for inetd\n");
    fprintf(stderr, "-W <receive_window_buffer> (default 24576, larger may be faster, max 10MB)\n");
    fprintf(stderr, "-K <keepalive>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-I <idle_timeout>  (0 is never, default 0, in seconds)\n");
    fprintf(stderr, "-z    disable QoS\n");
    fprintf(stderr, "-V    Version\n");
}

int parse_int_full(const char *s, long *out) {
    if (s == NULL || *s == '\0') return 0;
    char *end;
    errno = 0;
    long v = strtol(s, &end, 10);
    if (errno != 0) return 0;
    if (*end != '\0') return 0;
    *out = v;
    return 1;
}

int main(int argc, char *argv[]) {
    progname = argv[0];
    char *bannerfile = NULL;
    char **hostkeys = NULL;
    int hostkeys_count = 0;
    int hostkeys_cap = 0;
    char *auth_dir = NULL;
    int gen_hostkeys = 0;
    int foreground = 0;
    int pass_env = 0;
    int no_motd = 0;
    int no_root = 0;
    char *group_name = NULL;
    int no_password = 0;
    int no_root_password = 0;
    int blank_password = 0;
    int two_factor = 0;
    long max_tries = 10;
    int no_local_forward = 0;
    int no_remote_forward = 0;
    int allow_any_forward = 0;
    char *forced_command = NULL;
    char **ports = NULL;
    int ports_count = 0;
    int ports_cap = 0;
    char *pidfile = NULL;
    char *interface = NULL;
    int inetd = 0;
    long recv_window = 24576;
    long keepalive = 0;
    long idle_timeout = 0;
    int disable_qos = 0;

    char *T_str = NULL;
    char *K_str = NULL;
    char *I_str = NULL;
    char *W_str = NULL;

    int i = 1;
    while (i < argc) {
        char *arg = argv[i];
        if (arg[0] != '-') {
            log_msg("Early exit: Invalid argument: %s", arg);
            exit(1);
        }
        if (strcmp(arg, "-") == 0) {
            log_msg("Early exit: Invalid argument: -");
            exit(1);
        }
        size_t len = strlen(arg);
        size_t j = 1;
        while (j < len) {
            char opt = arg[j];
            if (opt == 'h') {
                print_help();
                exit(0);
            }
            if (opt == 'V') {
                print_version();
                exit(0);
            }
            int requires_arg = (opt=='b' || opt=='r' || opt=='D' || opt=='G' || opt=='T' || opt=='W' || opt=='K' || opt=='I' || opt=='c' || opt=='p' || opt=='P' || opt=='l');
            if (requires_arg) {
                char *value = NULL;
                if (j+1 < len) {
                    value = arg + j + 1;
                } else {
                    if (i+1 >= argc) {
                        log_msg("Early exit: Missing argument");
                        exit(1);
                    }
                    i++;
                    value = argv[i];
                }
                switch (opt) {
                    case 'b': bannerfile = value; break;
                    case 'r': {
                        if (hostkeys_count >= hostkeys_cap) {
                            hostkeys_cap = hostkeys_cap ? hostkeys_cap*2 : 4;
                            hostkeys = realloc(hostkeys, hostkeys_cap * sizeof(char*));
                        }
                        hostkeys[hostkeys_count++] = value;
                        break;
                    }
                    case 'D': auth_dir = value; break;
                    case 'G': group_name = value; break;
                    case 'T': T_str = value; break;
                    case 'W': W_str = value; break;
                    case 'K': K_str = value; break;
                    case 'I': I_str = value; break;
                    case 'c': forced_command = value; break;
                    case 'p': {
                        if (value[0] == '\0') {
                            int *p = NULL;
                            *p = 1;
                        }
                        if (ports_count >= ports_cap) {
                            ports_cap = ports_cap ? ports_cap*2 : 8;
                            ports = realloc(ports, ports_cap * sizeof(char*));
                        }
                        ports[ports_count++] = value;
                        break;
                    }
                    case 'P': pidfile = value; break;
                    case 'l': interface = value; break;
                }
                break;
            } else {
                switch (opt) {
                    case 'R': gen_hostkeys = 1; break;
                    case 'F': foreground = 1; break;
                    case 'e': pass_env = 1; break;
                    case 'm': no_motd = 1; break;
                    case 'w': no_root = 1; break;
                    case 's': no_password = 1; break;
                    case 'g': no_root_password = 1; break;
                    case 'B': blank_password = 1; break;
                    case 't': two_factor = 1; break;
                    case 'j': no_local_forward = 1; break;
                    case 'k': no_remote_forward = 1; break;
                    case 'a': allow_any_forward = 1; break;
                    case 'i': inetd = 1; break;
                    case 'z': disable_qos = 1; break;
                    default: {
                        fprintf(stderr, "Invalid option -%c\n", opt);
                        print_help();
                        exit(1);
                    }
                }
                j++;
                continue;
            }
        }
        i++;
    }

    // Bad port
    for (int p = 0; p < ports_count; p++) {
        char *ps = ports[p];
        char *colon = strrchr(ps, ':');
        if (colon) {
            char *portpart = colon+1;
            if (portpart[0] == '\0') {
                log_msg("Early exit: Bad port");
                exit(1);
            }
        }
    }

    // Banner
    if (bannerfile) {
        struct stat st;
        if (stat(bannerfile, &st) != 0) {
            log_msg("Error opening banner file '%s'", bannerfile);
        } else {
            if (st.st_size > 2050) {
                log_msg("Banner file too large, max is 2050 bytes");
            } else if (S_ISDIR(st.st_mode)) {
                log_msg("Error reading banner file '%s'", bannerfile);
            } else {
                FILE *f = fopen(bannerfile, "r");
                if (!f) {
                    log_msg("Error reading banner file '%s'", bannerfile);
                } else {
                    char buf[4096];
                    size_t n = fread(buf, 1, sizeof(buf), f);
                    if (ferror(f)) {
                        log_msg("Error reading banner file '%s'", bannerfile);
                    } else if (n > 2050) {
                        log_msg("Banner file too large, max is 2050 bytes");
                    }
                    fclose(f);
                }
            }
        }
    }

    // Group
    if (group_name) {
        struct group *gr = getgrnam(group_name);
        if (!gr) {
            log_msg("Early exit: Cannot restrict logins to group '%s' as the group does not exist", group_name);
            exit(1);
        }
    }

    // W
    if (W_str) {
        long v;
        if (!parse_int_full(W_str, &v) || v <= 0) {
            log_msg("Bad recv window '%s', using 24576", W_str);
            recv_window = 24576;
        } else if (v > 10485760) {
            log_msg("Bad recv window '%s', using 10485760", W_str);
            recv_window = 10485760;
        } else {
            recv_window = v;
        }
    }

    // T
    if (T_str) {
        long v;
        if (!parse_int_full(T_str, &v) || v < 0) {
            log_msg("Early exit: Bad maxauthtries '%s'", T_str);
            exit(1);
        }
        if (v > INT_MAX) {
            log_msg("Early exit: Bad maxauthtries '%s'", T_str);
            exit(1);
        }
        max_tries = v;
    }

    // K
    if (K_str) {
        long v;
        if (!parse_int_full(K_str, &v) || v < 0) {
            log_msg("Early exit: Bad keepalive '%s'", K_str);
            exit(1);
        }
        if (v > INT_MAX) {
            log_msg("Early exit: Bad keepalive '%s'", K_str);
            exit(1);
        }
        keepalive = v;
    }

    // I
    if (I_str) {
        long v;
        if (!parse_int_full(I_str, &v) || v < 0) {
            log_msg("Early exit: Bad idle_timeout '%s'", I_str);
            exit(1);
        }
        if (v > INT_MAX) {
            log_msg("Early exit: Bad idle_timeout '%s'", I_str);
            exit(1);
        }
        idle_timeout = v;
    }

    if (forced_command) {
        log_msg("Forced command set to '%s'", forced_command);
    }

    if (two_factor && no_password) {
        log_msg("Early exit: -t and -s are incompatible");
        exit(1);
    }

    const char *default_hostkeys[] = {
        "/etc/dropbear/dropbear_rsa_host_key",
        "/etc/dropbear/dropbear_ecdsa_host_key",
        "/etc/dropbear/dropbear_ed25519_host_key"
    };
    int default_count = 3;
    char **keys_to_try = NULL;
    int keys_to_try_count = 0;
    if (hostkeys_count > 0) {
        keys_to_try = hostkeys;
        keys_to_try_count = hostkeys_count;
    } else {
        keys_to_try = (char**)default_hostkeys;
        keys_to_try_count = default_count;
    }

    int valid_hostkeys = 0;
    for (int k = 0; k < keys_to_try_count; k++) {
        char *path = keys_to_try[k];
        FILE *f = fopen(path, "rb");
        if (!f) {
            if (!gen_hostkeys) log_msg("Failed loading %s", path);
            continue;
        }
        fseek(f, 0, SEEK_END);
        long fsize = ftell(f);
        fseek(f, 0, SEEK_SET);
        if (fsize < 0) {
            fclose(f);
            if (!gen_hostkeys) log_msg("Failed loading %s", path);
            continue;
        }
        if (fsize < 4) {
            fclose(f);
            log_msg("Early exit: Bad buf_getptr");
            exit(1);
        }
        unsigned char *data = malloc(fsize);
        if (!data) {
            fclose(f);
            if (!gen_hostkeys) log_msg("Failed loading %s", path);
            continue;
        }
        size_t rd = fread(data,1,fsize,f);
        fclose(f);
        if (rd != (size_t)fsize) {
            free(data);
            if (!gen_hostkeys) log_msg("Failed loading %s", path);
            continue;
        }
        unsigned long l = ((unsigned long)data[0]<<24)|((unsigned long)data[1]<<16)|((unsigned long)data[2]<<8)|(unsigned long)data[3];
        if (l > 9000) {
            free(data);
            log_msg("Early exit: String too long");
            exit(1);
        }
        if (l + 4 > (unsigned long)fsize) {
            free(data);
            log_msg("Early exit: Bad buf_getptr");
            exit(1);
        }
        if (l == 11 && fsize >= 4+11+4 && memcmp(data+4, "ssh-ed25519", 11)==0) {
            unsigned long off = 4+l;
            unsigned long l2 = ((unsigned long)data[off]<<24)|((unsigned long)data[off+1]<<16)|((unsigned long)data[off+2]<<8)|(unsigned long)data[off+3];
            if (l2 > 9000) {
                free(data);
                log_msg("Early exit: String too long");
                exit(1);
            }
            if (off+4+l2 > (unsigned long)fsize) {
                free(data);
                log_msg("Early exit: Bad buf_getptr");
                exit(1);
            }
            valid_hostkeys++;
            free(data);
            continue;
        }
        if (fsize == (long)(l+4) && l >= 1697) {
            free(data);
            log_msg("Early exit: Bad buf_getptr");
            exit(1);
        }
        if (l >= 1697) {
            free(data);
            log_msg("Early exit: Bad buf_getptr");
            exit(1);
        }
        free(data);
        if (!gen_hostkeys) log_msg("Failed loading %s", path);
    }
    if (valid_hostkeys==0 && !gen_hostkeys) {
        log_msg("Early exit: No hostkeys available. 'dropbear -R' may be useful or run dropbearkey.");
        exit(1);
    }

    if (ports_count==0) {
        ports = malloc(sizeof(char*));
        ports[0]="22";
        ports_count=1;
        ports_cap=1;
    }

    if (inetd) {
        struct sockaddr_storage ss;
        socklen_t sl = sizeof(ss);
        if (getsockname(0, (struct sockaddr*)&ss, &sl)!=0) {
            log_msg("Early exit: Failed socket address: Socket operation on non-socket");
            exit(1);
        }
    }

    if (interface) {
        log_msg("Binding to interface '%s'", interface);
    }

    int iface_exists = 0;
    if (interface) {
        if (if_nametoindex(interface)!=0) iface_exists=1;
    }

    int successful = 0;
    char *pidfile_path = pidfile ? pidfile : "/var/run/dropbear.pid";

    for (int p=0;p<ports_count;p++) {
        char *spec = ports[p];
        char *dup = strdup(spec);
        char *addr=NULL;
        char *port=NULL;
        char *last = strrchr(dup, ':');
        if (last) {
            if (last==dup) {
                addr=NULL;
                port=last+1;
            } else {
                *last='\0';
                addr=dup;
                port=last+1;
                if (addr[0]=='\0') addr=NULL;
            }
        } else {
            addr=NULL;
            port=dup;
        }

        struct addrinfo hints, *res, *rp;
        memset(&hints,0,sizeof(hints));
        hints.ai_family=AF_UNSPEC;
        hints.ai_socktype=SOCK_STREAM;
        hints.ai_flags=AI_PASSIVE;
        int gai = getaddrinfo(addr, port, &hints, &res);
        const char *log_spec = spec;
        // For logging Failed listening, original logs only port part if colon present
        if (strchr(spec, ':')) {
            char *c = strrchr(spec, ':');
            log_spec = c+1;
        }

        if (gai!=0) {
            log_msg("Failed listening on '%s': Error resolving: %s", log_spec, gai_strerror(gai));
            free(dup);
            continue;
        }

        int any_success = 0;
        int first_errno = 0;
        for (rp=res; rp!=NULL; rp=rp->ai_next) {
            int s = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
            if (s<0) continue;
            if (interface) {
                if (!iface_exists) {
                    log_msg("Couldn't set SO_BINDTODEVICE");
                } else {
                    if (setsockopt(s, SOL_SOCKET, SO_BINDTODEVICE, interface, strlen(interface))<0) {
                        log_msg("Couldn't set SO_BINDTODEVICE");
                    }
                }
            }
            int opt=1;
            setsockopt(s, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
            if (bind(s, rp->ai_addr, rp->ai_addrlen)==0 && listen(s,10)==0) {
                any_success=1;
                successful++;
                continue;
            } else {
                if (first_errno==0) first_errno=errno;
            }
            close(s);
        }

        if (!any_success) {
            if (first_errno==EADDRINUSE) {
                log_msg("Failed listening on '%s': Error listening: Address already in use", log_spec);
            } else if (first_errno!=0) {
                log_msg("Failed listening on '%s': Error listening: %s", log_spec, strerror(first_errno));
            }
        }

        freeaddrinfo(res);
        free(dup);
    }

    if (successful==0) {
        log_msg("Early exit: No listening ports available.");
        exit(1);
    }

    if (foreground) {
        FILE *pf = fopen(pidfile_path,"w");
        if (pf) {
            fprintf(pf,"%d\n",(int)getpid());
            fclose(pf);
        }
        log_msg("Not backgrounding");
        while(1) sleep(1000);
    } else {
        if (!inetd) {
            pid_t pid = fork();
            if (pid<0) exit(1);
            if (pid>0) exit(0);
            setsid();
            FILE *pf = fopen(pidfile_path,"w");
            if (pf) {
                fprintf(pf,"%d\n",(int)getpid());
                fclose(pf);
            }
            log_msg("Running in background");
            while(1) sleep(1000);
        } else {
            FILE *pf = fopen(pidfile_path,"w");
            if (pf) {
                fprintf(pf,"%d\n",(int)getpid());
                fclose(pf);
            }
            log_msg("Not backgrounding");
            while(1) sleep(1000);
        }
    }
    return 0;
}
